#!/usr/bin/env python3
import argparse,json,os,threading,concurrent.futures,sys
sys.dont_write_bytecode=True
from pathlib import Path
from research_sdk import Client
from graders import grade
from judge import grade_with_helper

class EvidenceClient(Client):
 def __init__(self,*a,**kw):
  super().__init__(*a,**kw);self.original_replies={};self.auxiliary_replies={}
 def chat(self,*a,**kw):
  reply=super().chat(*a,**kw)
  if kw.get('item_id') is not None:
   if kw.get('model') in ('helper-grader','helper-simulator'):self.auxiliary_replies.setdefault(kw['item_id'],[]).append(reply)
   else:self.original_replies[kw['item_id']]=reply
  return reply
ROOT=Path(__file__).resolve().parent

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--context',required=True);ap.add_argument('--output',required=True);args=ap.parse_args()
 client=EvidenceClient(args.context);tasks=json.loads((ROOT/'tasks.json').read_text());manifest=json.loads((ROOT/'evaluation.json').read_text())
 rows={k:v for k,v in client.completed_items.items() if k in {t['id'] for t in tasks}}
 lock=threading.Lock();out=Path(args.output);out.parent.mkdir(parents=True,exist_ok=True)
 def persist():
  data={'protocol_version':1,'items':[rows[t['id']] for t in tasks if t['id'] in rows]}
  domain_scores={};coverage={}
  for domain,rule in manifest['domain_aggregations'].items():
   weights=rule['weights'];complete=[i for i in weights if i in rows and rows[i].get('execution_status')=='completed']
   coverage[domain]={'completed':len(complete),'declared':len(weights)}
   if len(complete)==len(weights):domain_scores[domain]=sum(weights[i]*rows[i]['score'] for i in weights)/sum(weights.values())
  data['domain_coverage']=coverage
  if len(domain_scores)==3:data['domain_scores']=domain_scores
  tmp=out.with_name(out.name+'.tmp');tmp.write_text(json.dumps(data,indent=2));os.replace(tmp,out)
 def run(t):
  r=client.item(t['id'],t['prompt'],lambda text:grade_with_helper(client,t,text) if t['grader']['kind']=='rubric_judge' else grade(text,t['grader']),max_tokens=t['max_tokens'])
  # Original recovered rows are preserved unchanged.
  if t['id'] not in client.completed_items:
   r['question_id']=t['id']
   if t['id'] in client.original_replies:
    original=client.original_replies[t['id']]
    r['response_text']=original['text'];r['raw_response']=original['response']
   if t['id'] in client.auxiliary_replies:r['auxiliary_calls']=client.auxiliary_replies[t['id']]
  with lock:rows[t['id']]=r;persist();print(t['id'],r['execution_status'],r['score'],r.get('answer_status'),r.get('finish_reason'),flush=True)
 persist()
 with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
  futures=[pool.submit(run,t) for t in tasks]
  for f in concurrent.futures.as_completed(futures):f.result()
 persist()
if __name__=='__main__':main()
