    raw=ctx.eval('JSON.stringify((()=>{const d=JSON.parse('+json.dumps(json.dumps(case['input']))+');const b=JSON.stringify(d);const v=solve(d);if(JSON.stringify(d)!==b)throw new Error("input mutated");return v;})())')
    result=json.loads(raw)
    results.append({'pass':same(result,case['output'],1e-8)})
   except (quickjs.JSException,ValueError,TypeError) as e:results.append({'pass':False,'error':type(e).__name__,'detail':str(e)[:240]})
  return {'score':sum(x['pass'] for x in results)/len(results),'answer_status':'answered','test_results':results}
 if kind=='sql':
  blocks=re.findall(r'```(?:sql|sqlite)?\s*\n(.*?)```',text,re.S)
  query=blocks[-1] if blocks else text.strip()
  results=[]
  for case in spec['cases']:
   db=sqlite3.connect(':memory:');db.executescript(spec['schema'])
   for table,rows in case['tables'].items():
    if rows:db.executemany('INSERT INTO '+table+' VALUES ('+','.join('?' for _ in rows[0])+')',rows)
   allowed={sqlite3.SQLITE_SELECT,sqlite3.SQLITE_READ,sqlite3.SQLITE_FUNCTION,sqlite3.SQLITE_RECURSIVE}
   db.set_authorizer(lambda action,*rest:sqlite3.SQLITE_OK if action in allowed else sqlite3.SQLITE_DENY)
   steps=[0]
   def progress():
    steps[0]+=1
    return int(steps[0]>1000)
   db.set_progress_handler(progress,1000)
   try:
    result=[list(r) for r in db.execute(query).fetchall()]
    results.append({'pass':same(result,case['output'],1e-8)})
   except sqlite3.Error as e:results.append({'pass':False,'error':type(e).__name__,'detail':str(e)[:240]})
   finally:db.close()
  return {'score':sum(x['pass'] for x in results)/len(results),'answer_status':'answered','test_results':results}
 raise ValueError('Unknown frozen grader '+kind)
