  except json.JSONDecodeError:return None
 ids={c['id'] for c in criteria}
 if not isinstance(obj,dict) or set(obj)!={'criteria'}:return None
 values=obj['criteria']
 if not isinstance(values,dict) or set(values)!=ids:return None
 if any(type(v) is not int or v not in (0,1) for v in values.values()):return None
 return values

def grade_with_helper(client,task,text):
